from pysat.solvers import Glucose3

# Generate all APs of length 4 in {1, ..., 41}
# Variables: x_1, ..., x_41, where x_i = True means color 1
# We'll use 1-indexed variable numbers for pysat

clauses = []

for a in range(1, 42):
    for d in range(1, 42):
        if a + 3*d <= 41:
            ap = [a, a+d, a+2*d, a+3*d]
            # Not all color 1: at least one is 0
            clauses.append([-v for v in ap])
            # Not all color 0: at least one is 1
            clauses.append(ap)

print(f"Number of APs: {len(clauses)//2}")
print(f"Number of clauses: {len(clauses)}")

solver = Glucose3()
for clause in clauses:
    solver.add_clause(clause)

sat_result = solver.solve()
print(f"SAT result: {sat_result}")

if sat_result:
    model = solver.get_model()
    # Convert to coloring: 0 or 1 for each position 1..41
    coloring = []
    for i in range(1, 42):
        if i in model:
            coloring.append(1)
        elif -i in model:
            coloring.append(0)
        else:
            coloring.append(0)  # arbitrary if unassigned
    print(f"Coloring: {coloring}")

    # Verify
    for a in range(1, 42):
        for d in range(1, 42):
            if a + 3*d <= 41:
                colors = [coloring[a-1], coloring[a+d-1], coloring[a+2*d-1], coloring[a+3*d-1]]
                if all(c == 0 for c in colors) or all(c == 1 for c in colors):
                    print(f"BAD AP found: a={a}, d={d}, colors={colors}")
                    break
        else:
            continue
        break
    else:
        print("Verification passed!")
else:
    print("UNSAT - no valid coloring exists")
